#' Import and tidy Cerillo growth curve data
#'
#' Reads a Cerillo Excel workbook generated by `cerillo_excel()`,
#' merges OD600 measurements with experimental metadata from the
#' map sheet, calculates smoothed growth curves, and returns both
#' raw and summarized datasets.
#'
#' @param filename Path to a Cerillo Excel workbook containing
#' sheets named "dat" and "map".
#'
#' @param Time_int Time interval between consecutive measurements
#' in minutes. Default = 10.
#'
#' @param range Excel column range containing OD600 measurements.
#' Default = "A:CR".
#'
#' @return A named list containing:
#' \describe{
#'   \item{data}{
#'   Long-format dataset containing well metadata, OD600 values,
#'   rolling-median values, and smoothed OD600 values.}
#'
#'   \item{summary}{
#'   Summary statistics grouped by experimental variables,
#'   including means, standard deviations, and replicate counts.}
#' }
#'
#' @export

load_cerillo <- function(filename,
                         Time_int = 10,
                         range = "A:CR") {

  # -------------------------------------------------------------------------
  # Verify required packages are available
  # -------------------------------------------------------------------------

  required_packages <- c(
    "readxl",
    "janitor",
    "dplyr",
    "tidyr",
    "data.table",
    "cellranger",
    "zoo"
  )

  missing_packages <- required_packages[
    !sapply(required_packages, requireNamespace, quietly = TRUE)
  ]

  if (length(missing_packages) > 0) {

    install_commands <- paste0(
      "install.packages('",
      missing_packages,
      "')"
    )

    stop(
      paste(
        "The following packages are required:",
        paste(missing_packages, collapse = ", "),
        "\nPlease install using:",
        paste(install_commands, collapse = " or ")
      )
    )
  }

  # -------------------------------------------------------------------------
  # Verify workbook structure
  # -------------------------------------------------------------------------

  sheets <- readxl::excel_sheets(filename)

  if (!"dat" %in% sheets) {
    stop("Sheet 'dat' not found in workbook.")
  }

  if (!"map" %in% sheets) {
    stop("Sheet 'map' not found in workbook.")
  }

  # -------------------------------------------------------------------------
  # Import measurement data and plate map
  # -------------------------------------------------------------------------

  dat <- readxl::read_excel(
    filename,
    sheet = "dat",
    range = cellranger::cell_cols(range)
  )

  map <- readxl::read_excel(
    filename,
    sheet = "map"
  ) |>
    # Remove user-added columns that were left completely blank
    janitor::remove_empty(which = "cols") |>
    # Convert metadata columns to character to ensure consistent joins
    dplyr::mutate(
      dplyr::across(
        tidyselect::everything(),
        as.character
      )
    )

  if (!"Well" %in% names(map)) {
    stop(
      "The 'map' sheet must contain a column named 'Well'."
    )
  }

  # -------------------------------------------------------------------------
  # Create experiment time vector
  # -------------------------------------------------------------------------
  #
  # Generate one time point for each measurement row in the
  # imported dataset, starting at t = 0.
  # -------------------------------------------------------------------------

  time_vector <- seq(
    from = 0,
    by = Time_int,
    length.out = nrow(dat)
  )

  # -------------------------------------------------------------------------
  # Convert plate-reader output into tidy format
  # -------------------------------------------------------------------------
  #
  # The imported data contains one column per well. Here we:
  #   1. Transpose the data.
  #   2. Add well identifiers.
  #   3. Merge experimental metadata from the map sheet.
  #   4. Convert measurements into long format.
  #   5. Calculate smoothed growth curves.
  # -------------------------------------------------------------------------

  df <- data.table::transpose(dat) |>
    dplyr::mutate(
      Well = colnames(dat),
      .before = V1
    ) |>
    dplyr::left_join(map, by = "Well") |>
    janitor::clean_names(case = "upper_camel") |>
    tidyr::pivot_longer(
      cols = where(is.double),
      names_to = "Time",
      values_to = "OD600"
    ) |>
    dplyr::mutate(
      Time = rep(
        time_vector,
        times = ncol(dat)
      )
    ) |>
    dplyr::group_by(
      dplyr::across(c(-Time, -OD600))
    ) |>

    # Apply two-stage smoothing:
    #   1. Rolling median reduces spikes and outliers.
    #   2. Rolling mean smooths remaining measurement noise.
    dplyr::mutate(
      RollingMedian = zoo::rollmedian(
        OD600,
        k = 3,
        fill = "extend"
      ),
      SmoothedOD600 = zoo::rollmean(
        RollingMedian,
        k = 3,
        fill = "extend"
      )
    ) |>
    dplyr::ungroup()

  # -------------------------------------------------------------------------
  # Calculate summary statistics across replicate groups
  # -------------------------------------------------------------------------

  df_summary <- df |>
    dplyr::group_by(
      dplyr::across(
        c(
          -Well,
          -OD600,
          -RollingMedian,
          -SmoothedOD600
        )
      )
    ) |>
    dplyr::summarise(
      mean_od600 = mean(OD600),
      sd_od600 = sd(OD600),
      mean_smoothed_od600 = mean(SmoothedOD600),
      sd_smoothed_od600 = sd(SmoothedOD600),
      reps = dplyr::n(),
      .groups = "drop"
    )

  # -------------------------------------------------------------------------
  # Return both detailed and summarized datasets
  # -------------------------------------------------------------------------

  return(
    list(
      data = df,
      summary = df_summary
    )
  )
}
